import json,html
from pathlib import Path
root=Path(__file__).resolve().parent.parent
p=json.loads((root/'content/profile.json').read_text());esc=html.escape
link=p['linkedin']
font='/assets/media/1avCW4o2ktVQv0oQpAZepUn47lw.woff2'
styles='''
@font-face{font-family:Portfolio;src:url(FONT) format("woff2");font-display:swap}*{box-sizing:border-box}body{margin:0;background:#fcfcfc;color:#050605;font-family:Portfolio,Arial,sans-serif}a{color:inherit;text-decoration:none}header{padding:24px 40px;display:flex;align-items:center;justify-content:space-between;gap:24px}header>a{font-weight:700;font-size:26px;letter-spacing:-2px}nav{display:flex;gap:28px;font-size:15px}nav a:hover,footer a:hover{text-decoration:underline}main{max-width:1600px;margin:auto;padding:90px 40px 120px}.eyebrow{font:12px/1.5 monospace;text-transform:uppercase;letter-spacing:.06em}h1{font-size:clamp(55px,8vw,128px);font-weight:500;letter-spacing:-.07em;line-height:1;margin:22px 0 38px;max-width:1200px}.intro{max-width:640px;font-size:clamp(20px,2vw,30px);line-height:1.4;letter-spacing:-.025em}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:64px 32px;margin-top:70px}.cover{height:360px;border-radius:24px;background:#d9d9d0;position:relative;overflow:hidden;display:grid;place-items:center;font-size:clamp(35px,4vw,72px);letter-spacing:-.065em;transition:transform .4s}.cover::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 31px,#2222220d 31px 32px),repeating-linear-gradient(90deg,transparent 0 31px,#2222220d 31px 32px)}.cover span{position:relative}.card:hover .cover{transform:translateY(-8px)}.card:nth-child(2) .cover{background:#c6cadb}.card:nth-child(3) .cover{background:#202b27;color:#c9f8bc}.card:nth-child(4) .cover{background:#d9dbca}.card:nth-child(5) .cover{background:#ded0c4}.card h2{font-size:30px;font-weight:500;letter-spacing:-.04em;margin:20px 0 8px}.card p{font-size:17px;line-height:1.55;max-width:600px}.tag{font:11px/1.5 monospace;letter-spacing:.04em}.button{display:inline-flex;background:#080908;color:white;border-radius:99px;padding:18px 24px;margin-top:28px;gap:30px;transition:background .2s}.button:hover{background:#314736}.detail{margin-top:60px;max-width:960px}.detail.cover{height:480px}footer{padding:60px 40px 30px;background:#050605;color:#fcfcfc;border-radius:32px 32px 0 0}footer h2{font-weight:500;font-size:clamp(40px,7vw,110px);letter-spacing:-.06em;max-width:1100px;line-height:1.05;margin:0 0 40px}.footline{display:flex;justify-content:space-between;margin-top:90px;font-size:14px}a:focus-visible{outline:3px solid #6d9474;outline-offset:6px}@media(prefers-reduced-motion:no-preference){main{animation:appear .65s ease both}@keyframes appear{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}}@media(max-width:700px){header{padding:24px 20px;align-items:flex-start}nav{gap:12px;flex-wrap:wrap;justify-content:flex-end;font-size:13px;max-width:280px}main{padding:60px 20px 80px}.grid{grid-template-columns:1fr;gap:40px}.cover{height:300px}.detail.cover{height:320px}footer{padding:40px 20px}.footline{margin-top:60px}}
'''.replace('FONT',font)
def shell(title,content):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{esc(title)} — Lea Irt</title><meta name="description" content="{esc(p['bio'])}"><style>{styles}</style></head><body><header><a href="/" aria-label="Lea Irt home">LI</a><nav aria-label="Main navigation"><a href="/">Home</a><a href="/about">About</a><a href="/projects">Projects</a><a href="/playground">Playground</a><a href="/lets-connect">Let's connect ↗</a></nav></header><main>{content}</main><footer><h2>let's create<br>something cool.</h2><a href="{link}" target="_blank" rel="noopener noreferrer">Connect on LinkedIn ↗</a><div class="footline"><span>Lea Irt</span><span>© 2026</span></div></footer></body></html>'''
def write(route,content):
 path=root/route/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content)
def cards(projects):
 return '<div class="grid">'+''.join(f'''<a class="card" href="/work/{q['slug']}"><div class="cover"><span>{esc(q['cover'])}</span></div><h2>{esc(q['title'])} ↗</h2><span class="tag">{esc(q['category'])}</span><p>{esc(q['description'])}</p></a>''' for q in projects)+'</div>'
write('projects',shell('Projects','<div class="eyebrow">(SELECTED WORK)</div><h1>Selected projects</h1>'+cards(p['projects'])))
write('playground',shell('Playground','<div class="eyebrow">(EXPERIMENTS)</div><h1>Playground</h1><p class="intro">Algorithms, games and ideas in motion.</p>'+cards([p['projects'][2],p['projects'][4],p['projects'][1]])))
for q in p['projects']:
 content=f'''<div class="eyebrow">{esc(q['category'])}</div><h1>{esc(q['title'])}</h1><p class="intro">{esc(q['description'])}</p><a class="button" href="{link}" target="_blank" rel="noopener noreferrer">Project details on LinkedIn <span>↗</span></a><div class="detail cover" aria-hidden="true"><span>{esc(q['cover'])}</span></div><a class="button" href="/projects">← All projects</a>'''
 page=shell(q['title'],content)
 write('work/'+q['slug'],page)
 # Previously shared URLs also resolve to the corresponding personalized project.
 write('projects/'+q['oldSlug'],page)
print('Built personal project, playground and detail pages.')
